import rclpy
from rclpy.node import Node
from rclpy.qos import QoSProfile, ReliabilityPolicy, DurabilityPolicy, HistoryPolicy
from geometry_msgs.msg import Pose

from wyrm_msgs.msg import Description, Frame

class WyrmMocapBridge(Node):

    def __init__(self):
        super().__init__('wyrm_mocap_bridge')
        
        self.id_to_name_map = {}
        self.active_publishers = {}
        
        description_qos = QoSProfile(
            reliability=ReliabilityPolicy.RELIABLE,
            durability=DurabilityPolicy.TRANSIENT_LOCAL,
            history=HistoryPolicy.KEEP_LAST,
            depth=10
        )
        
        frame_qos = QoSProfile(
            reliability=ReliabilityPolicy.RELIABLE,
            durability=DurabilityPolicy.VOLATILE,
            history=HistoryPolicy.KEEP_LAST,
            depth=1
        )
        
        self.description_sub = self.create_subscription(
            Description,                    # Message type
            '/WyrmDescription',             # Topic name
            self.description_callback,      # Callback function
            description_qos                 # QoS profile / Queue size
        )
        
        self.frame_sub = self.create_subscription(
            Frame,                          # Message type
            '/WyrmFrame',                   # Topic name
            self.frame_callback,            # Callback function
            frame_qos                       # QoS profile / Queue size                      
        )
        
        self.get_logger().info("Wyrm Mocap Bridge started and listening...")

    def description_callback(self, msg: Description):
        if msg.id not in self.id_to_name_map:
            self.id_to_name_map[msg.id] = msg.name
            self.get_logger().info(f"Registered robot profile: ID {msg.id} -> Name: '{msg.name}'")
            
    def frame_callback(self, msg: Frame):
        for body in msg.bodies:
            body_id = body.id
            
            if not body.tracking_lost: 
                continue
            
            robot_name = self.id_to_name_map.get(body_id, body.name)
            
            if not robot_name:
                robot_name = f"UnknownRobot_{body_id}"
                
            if robot_name not in self.active_publishers:
                topic_name = f"/{robot_name}_pos"
                
                self.active_publishers[robot_name] = self.create_publisher(
                    Pose,
                    topic_name,
                    10
                )
                self.get_logger().info(f"Dynamically spun up streaming topic: {topic_name}")

            # Construct the final Pose message to emit to the ROS2 graph
            pose_msg = Pose()
            
            # Map position and orientation from the incoming WyrmRigidBody payload
            pose_msg.position = body.position
            pose_msg.orientation = body.orientation

            # Push the data to the dedicated robot topic
            self.active_publishers[robot_name].publish(pose_msg)

def main(args=None):
    rclpy.init(args=args)
    node = WyrmMocapBridge()
    try:
        rclpy.spin(node)
    except (KeyboardInterrupt, SystemExit):
        pass
    finally:
        print("Trying to shutdown")
        rclpy.try_shutdown()

if __name__ == '__main__':
    main()